/** One member as a row of the table surface, on the columns of the card view. */
export function MemberRow({ member, openTasks, actions }: MemberRowProps) {
  const [isActivityOpen, setIsActivityOpen] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const panelVariants = panelPresenceOf(shouldReduceMotion);
  const rowLayout = rowLayoutOf(shouldReduceMotion);
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const panelId = useId();
  const task = member.task;
  const worked = workedTodayOf(member);
  const isManager = member.role === 'manager';

  function toggleActivity() {
    setIsActivityOpen((isOpen) => !isOpen);
  }

  function changeEstimate(minutes: number) {
    actions.changeEstimate(member.id, minutes);
  }

  return (
    <motion.div
      role='row'
      layout='position'
      transition={rowLayout}
      variants={rowPresence}
      initial='hidden'
      animate='shown'
      exit='hidden'
      className={cn(TABLE_GRID, 'bg-card', member.isCurrentUser && OWN_ROW)}
    >
