            <span className='truncate'>{member.name}</span>
            {member.isCurrentUser && (
              <Chip color='var(--muted-foreground)'>You</Chip>
            )}
          </p>
          <p className='text-muted-foreground hidden truncate text-xs md:block'>
            {member.title}
            {isManager && ' · Manager'}
          </p>
          <PhoneTaskLine member={member} />
        </div>
      </div>
      <div
        role='cell'
        className={cn(CELL, 'hairline-l border-border hidden md:flex')}
      >
        <TaskCell member={member} openTasks={openTasks} actions={actions} />
      </div>
      <div role='cell' className={cn(CELL, FIGURE_CELL)}>
        <DurationFigure minutes={worked} className='text-[13px] font-medium' />
      </div>
      <div role='cell' className={cn(CELL, FIGURE_CELL)}>
        {task && (
          <EstimateField
            minutes={member.estimateMinutes}
            taskNumber={task.number}
            onChange={changeEstimate}
