      </div>
      <div
        role='cell'
        className={cn(
          CELL,
          'md:hairline-l border-border justify-end px-2 md:justify-center md:px-4'
        )}
      >
        <TotalPill
          member={member}
          isOpen={isActivityOpen}
          panelId={panelId}
          onToggle={toggleActivity}
        />
