      <div
        role='cell'
        className={cn(
          CELL,
          'md:hairline-l border-border justify-center px-0 md:px-0'
        )}
      >
        <MemberMenu member={member} actions={actions} />
      </div>
      <AnimatePresence initial={false}>
        {isActivityOpen && (
          <motion.div
            key='activity'
            variants={panelVariants}
            initial='hidden'
            animate='shown'
            exit='hidden'
            className='col-span-full overflow-hidden'
          >
            <ActivityPanel
              member={member}
              panelId={panelId}
              actions={actions}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

